 * Counts an instant-runoff election round by round.
 */

/**
 * @param {string[]} candidateNames declared candidates, in declaration order
 * @param {{ count: number, names: string[] }[]} ballots parsed ballots
 * @returns {{ rounds: { counts: { name: string, votes: number }[], exhausted: number, eliminated: string|null }[], winner: string|null }}
 */
export function countRounds(candidateNames, ballots) {
  const totalBallots = ballots.reduce((sum, b) => sum + b.count, 0)
  let continuing = new Set(candidateNames)
  const history = [] // history[roundIndex] = Map<name, votes>, for rounds already counted
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)

    let activeTotal = 0
    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice !== undefined) {
        votes.set(choice, votes.get(choice) + ballot.count)
        activeTotal += ballot.count
      }
    }

    const exhausted = totalBallots - activeTotal
    history.push(votes)

    const counts = [...continuing]
      .map((name) => ({ name, votes: votes.get(name) }))
      .sort((a, b) => b.votes - a.votes || (a.name < b.name ? -1 : 1))

    const round = { counts, exhausted, eliminated: null }
    rounds.push(round)

    if (activeTotal === 0) {
      winner = null
      break
    }

    const majority = counts.find((c) => c.votes * 2 > activeTotal)
    if (majority) {
      winner = majority.name
      break
    }

    const eliminated = chooseElimination(continuing, votes, history)
    round.eliminated = eliminated
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/**
 * Picks the candidate to eliminate: the fewest votes this round, breaking
 * ties by comparing vote history from the first round onwards, and finally
 * by picking the name that sorts last by code point.
 */
function chooseElimination(continuing, votes, history) {
  const minVotes = Math.min(...[...continuing].map((name) => votes.get(name)))
  let tied = [...continuing].filter((name) => votes.get(name) === minVotes)

  for (let r = 0; r < history.length && tied.length > 1; r++) {
    const roundVotes = history[r]
    const min = Math.min(...tied.map((name) => roundVotes.get(name)))
    const survivors = tied.filter((name) => roundVotes.get(name) === min)
    if (survivors.length < tied.length) tied = survivors
  }

  if (tied.length === 1) return tied[0]
  return tied.reduce((a, b) => (a > b ? a : b))
}
"}

